/* Floating Add Transaction Button (FAB) */
.fab-add-transaction {
  position: fixed;
  right: 28px;
  bottom: 28px;
  z-index: 1100;
  width: 60px;
  height: 60px;
  border: none;
  background: var(--primary, #6c2ebe);
  color: #fff;
  border-radius: 50%;
  box-shadow: 0 4px 18px rgba(44,12,110,0.17), 0 0.5px 1.5px rgba(0,0,0,0.04);
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  font-size: 2rem;
  transition: box-shadow 0.18s, background 0.18s, transform 0.14s;
}

.fab-add-transaction:active,
.fab-add-transaction:focus {
  outline: none;
  background: #5521a9;
  box-shadow: 0 2px 10px rgba(44,12,110,0.22);
  transform: scale(0.97);
}

.fab-add-transaction:hover {
  background: #9147e0;
}

@media (max-width: 620px) {
  .fab-add-transaction {
    right: 16px;
    bottom: 16px;
    width: 52px;
    height: 52px;
    font-size: 1.7rem;
  }
